<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Requests\StoreMoodCheckinRequest; use App\Models\MoodCheckin; use App\Support\ApiResponse; use Illuminate\Support\Facades\DB;
class MoodCheckinController extends Controller {use ApiResponse; public function index(){return $this->paginated(request()->user()->moodCheckins()->with(['feelingExpression.feeling','causes','copingMechanisms'])->latest('checked_in_at')->paginate(min((int)request('per_page',20),100)));} public function today(){return response()->json(['checkin'=>request()->user()->moodCheckins()->with(['feelingExpression.feeling','causes','copingMechanisms'])->whereDate('checked_in_at',today())->latest('checked_in_at')->first()]);} public function store(StoreMoodCheckinRequest $r){$d=$r->validated();$m=DB::transaction(function()use($r,$d){$m=$r->user()->moodCheckins()->create(['feeling_expression_id'=>$d['feeling_exp_id'],'intensity'=>$d['intensity'],'journal'=>$d['journal']??null,'checked_in_at'=>now()]);$m->causes()->sync($d['reason_ids']??[]);$m->copingMechanisms()->sync($d['coping_mechanism_ids']??[]);return $m->load(['feelingExpression.feeling','causes','copingMechanisms']);});return $this->success($m,'Mood check-in created successfully.',201);}}
